fun {m} {motive} t mk =>
  BlockMatrixVector.RoundingTrace.rec.{u}
    (fun mulError blockAddError outerAddError => mk mulError blockAddError outerAddError) t

declarations.type:
∀ {m : Nat} {mulError blockAddError : Fin m → Nat → Nat → Real} {outerAddError : Fin m → Nat → Real}
  {mulError_1 blockAddError_1 : Fin m → Nat → Nat → Real} {outerAddError_1 : Fin m → Nat → Real},
  Eq.{1} { mulError := mulError, blockAddError := blockAddError, outerAddError := outerAddError }
      { mulError := mulError_1, blockAddError := blockAddError_1, outerAddError := outerAddError_1 } →
    And (Eq.{1} mulError mulError_1) (And (Eq.{1} blockAddError blockAddError_1) (Eq.{1} outerAddError outerAddError_1))

