fun {m n} T E i j =>
  have b := HDiv.hDiv.{0, 0, 0} (↑j) T;
  have t := HMod.hMod.{0, 0, 0} (↑j) T;
  HMul.hMul.{0, 0, 0}
    (HMul.hMul.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} 1 (BlockMatrixVector.RoundingTrace.mulError E i b t))
      (∏ s ∈ Finset.Ico.{0} (Max.max.{0} 1 t) T,
        HAdd.hAdd.{0, 0, 0} 1 (BlockMatrixVector.RoundingTrace.blockAddError E i b s)))
    (∏ s ∈ Finset.Ico.{0} (Max.max.{0} 1 b) (BlockMatrixVector.blockCount n T),
      HAdd.hAdd.{0, 0, 0} 1 (BlockMatrixVector.RoundingTrace.outerAddError E i s))
